#include <cstdio>
#include <cstring>
#include <cmath>
#include <cstdlib>
#include <vector>
#include <string>
#include <algorithm>
#include <queue>
#include <stack>
#include <deque>
#include <map>
#include <set>
#include <unordered_map>
#include <unordered_set>
#include <functional>
#include <numeric>
#include <sstream>
#include <iostream>
using namespace std;
int main(){int n,m;scanf("%d %d",&n,&m);
vector<vector<int>>g(n+1);
for(int i=0;i<m;++i){int u,v;scanf("%d %d",&u,&v);
g[u].push_back(v);g[v].push_back(u);}
if(m!=n-1){printf("NO\n");return 0;}
vector<bool>vis(n+1,false);queue<int>q;q.push(1);vis[1]=true;int cnt=1;
while(!q.empty()){int u=q.front();q.pop();
for(int v:g[u])if(!vis[v]){vis[v]=true;++cnt;q.push(v);}}
printf("%s\n",cnt==n?"YES":"NO");return 0;}

